{"command":"cat > /prediction.json <<'JSON'
{
  "vllm/v1/spec_decode/utils.py": {
    "eagle_prepare_next_token_padded_kernel": "@triton.jit\ndef eagle_prepare_next_token_padded_kernel(\n    sampled_token_ids_ptr,  # [num_reqs, num_sampled_tokens_per_req]\n    discard_request_mask_ptr,  # [num_reqs]\n    backup_next_token_ids_ptr,  # [num_reqs]\n    next_token_ids_ptr,  # [num_reqs] (output)\n    valid_sampled_tokens_count_ptr,  # [num_reqs] (output)\n    vocab_size,  # tl.int32\n    num_sampled_tokens_per_req,  # tl.int32 (num_spec_tokens + 1)\n    num_reqs,  # tl.int32\n    stride_sampled_token_ids,  # tl.int32 (stride for dim 0)\n    BLOCK_SIZE_TOKENS: tl.constexpr,  # Power-of-2 >= num_sampled_tokens_per_req\n):\n    req_idx = tl.program_id(0)\n    if req_idx >= num_reqs:\n        return\n\n    discard_req = tl.load(discard_request_mask_ptr + req_idx).to(tl.int1)\n    tok_offsets = tl.arange(0, BLOCK_SIZE_TOKENS)\n    tok_mask = tok_offsets < num_sampled_tokens_per_req\n    row_ptr = sampled_token_ids_ptr + req_idx * stride_sampled_token_ids + tok_offsets\n    sampled = tl.load(row_ptr, mask=tok_mask, other=-1)\n\n    valid = (sampled != -1) & (sampled < vocab_size) & (~discard_req) & tok_mask\n    valid_i32 = valid.to(tl.int32)\n    valid_count = tl.sum(valid_i32, axis=0)\n    tl.store(valid_sampled_tokens_count_ptr + req_idx, valid_count)\n\n    last_valid_idx = valid_count - 1\n    selected_token = tl.max(tl.where(valid, tok_offsets, 0), axis=0)\n    next_token = tl.load(backup_next_token_ids_ptr + req_idx)\n    has_valid = last_valid_idx >= 0\n    if has_valid:\n        next_token = tl.load(sampled_token_ids_ptr + req_idx * stride_sampled_token_ids + selected_token)\n    tl.store(next_token_ids_ptr + req_idx, next_token)\n",
    "eagle_prepare_inputs_padded_kernel": "@triton.jit\ndef eagle_prepare_inputs_padded_kernel(\n    cu_num_draft_tokens_ptr,  # [num_reqs]\n    valid_sampled_tokens_count_ptr,  # [num_reqs]\n    query_start_loc_gpu_ptr,  # [num_reqs + 1]\n    token_indices_to_sample_ptr,  # [num_reqs] (output)\n    num_reqs,  # tl.int32\n):\n    req_idx = tl.program_id(0)\n    if req_idx >= num_reqs:\n        return\n\n    cu_cur = tl.load(cu_num_draft_tokens_ptr + req_idx)\n    cu_prev = tl.where(req_idx > 0, tl.load(cu_num_draft_tokens_ptr + req_idx - 1), 0)\n    num_draft_tokens = cu_cur - cu_prev\n    valid_count = tl.load(valid_sampled_tokens_count_ptr + req_idx)\n    num_rejected_tokens = tl.where(\n        num_draft_tokens > 0,\n        num_draft_tokens + 1 - valid_count,\n        0,\n    )\n    query_end = tl.load(query_start_loc_gpu_ptr + req_idx + 1)\n    tl.store(token_indices_to_sample_ptr + req_idx, query_end - 1 - num_rejected_tokens)\n"
  },
  "vllm/v1/spec_decode/eagle.py": {
    "prepare_next_token_ids_padded": "def prepare_next_token_ids_padded(\n        self,\n        common_attn_metadata: CommonAttentionMetadata,\n        sampled_token_ids: torch.Tensor,\n        requests: dict[str, CachedRequestState],\n        gpu_input_batch: InputBatch,\n        discard_request_mask: torch.Tensor,\n    ) -> tuple[torch.Tensor, torch.Tensor]:\n        \"\"\"\n        Prepare per-request next token ids and valid sampled-token counts for\n        padded EAGLE speculation with a single fused GPU kernel.\n        \"\"\"\n        num_reqs = gpu_input_batch.num_reqs\n        self.backup_next_token_ids.np[:num_reqs] = np.asarray(\n            [\n                requests[gpu_input_batch.req_ids[i]].get_token_id(\n                    common_attn_metadata.seq_lens_cpu[i].item()\n                )\n                for i in range(num_reqs)\n            ],\n            dtype=np.int32,\n        )\n        self.backup_next_token_ids.copy_to_gpu(num_reqs)\n\n        next_token_ids = torch.empty(\n            (num_reqs,), dtype=torch.int32, device=sampled_token_ids.device\n        )\n        valid_sampled_tokens_count = torch.empty_like(next_token_ids)\n\n        num_sampled_tokens_per_req = sampled_token_ids.shape[1]\n        block_size_tokens = triton.next_power_of_2(num_sampled_tokens_per_req)\n\n        eagle_prepare_next_token_padded_kernel[(num_reqs,)](\n            sampled_token_ids,\n            discard_request_mask,\n            self.backup_next_token_ids.gpu,\n            next_token_ids,\n            valid_sampled_tokens_count,\n            gpu_input_batch.vocab_size,\n            num_sampled_tokens_per_req,\n            num_reqs,\n            sampled_token_ids.stride(0),\n            BLOCK_SIZE_TOKENS=block_size_tokens,\n        )\n\n        return next_token_ids, valid_sampled_tokens_count\n",
    "prepare_inputs_padded": "def prepare_inputs_padded(\n        self,\n        common_attn_metadata: CommonAttentionMetadata,\n        spec_decode_metadata: SpecDecodeMetadata,\n        valid_sampled_tokens_count: torch.Tensor,\n    ) -> tuple[CommonAttentionMetadata, torch.Tensor]:\n        \"\"\"\n        Prepare padded EAGLE attention metadata and per-request sampling indices\n        while avoiding extra lightweight GPU ops.\n        \"\"\"\n        query_start_loc_cpu = common_attn_metadata.query_start_loc_cpu\n        new_query_len_per_req = query_start_loc_cpu[1:] - query_start_loc_cpu[:-1]\n        total_num_tokens = int(query_start_loc_cpu[-1].item())\n\n        token_indices_to_sample = torch.empty(\n            (common_attn_metadata.num_reqs,),\n            dtype=torch.int32,\n            device=common_attn_metadata.query_start_loc.device,\n        )\n        eagle_prepare_inputs_padded_kernel[(common_attn_metadata.num_reqs,)](\n            spec_decode_metadata.cu_num_draft_tokens,\n            valid_sampled_tokens_count,\n            common_attn_metadata.query_start_loc,\n            token_indices_to_sample,\n            common_attn_metadata.num_reqs,\n        )\n\n        spec_common_attn_metadata = CommonAttentionMetadata(\n            query_start_loc=common_attn_metadata.query_start_loc,\n            seq_lens=common_attn_metadata.seq_lens,\n            query_start_loc_cpu=query_start_loc_cpu,\n            seq_lens_cpu=common_attn_metadata.seq_lens_cpu,\n            num_computed_tokens_cpu=common_attn_metadata.num_computed_tokens_cpu,\n            num_reqs=common_attn_metadata.num_reqs,\n            num_actual_tokens=total_num_tokens,\n            max_query_len=new_query_len_per_req.max().item(),\n            max_seq_len=common_attn_metadata.seq_lens_cpu.max().item(),\n            block_table_tensor=common_attn_metadata.block_table_tensor,\n            slot_mapping=common_attn_metadata.slot_mapping[:total_num_tokens],\n            causal=True,\n            dcp_local_seq_lens=common_attn_metadata.dcp_local_seq_lens,\n        )\n\n        return spec_common_attn_metadata, token_indices_to_sample\n"
  }
}
JSON"}

